const MARROW_SERIES = [
  { key: 'hsc', label: 'Stem cells (HSC)', color: 'var(--series-1)' },
  { key: 'neutrophil', label: 'Myeloid progenitors', color: 'var(--series-2)' },
  { key: 'platelet', label: 'Megakaryocyte progenitors', color: 'var(--series-3)' },
  { key: 'rbc', label: 'Erythroid progenitors', color: 'var(--series-4)' },
  { key: 'lymphocyte', label: 'Lymphoid progenitors', color: 'var(--series-5)' },
];
const GRADE_TEXT = [
  'No clinically significant cytopenia',
  'Mild cytopenia',
  'Moderate cytopenia',
  'Severe cytopenia',
  'Life-threatening cytopenia',
];

const state = {
  scenarioId: 'acute-4',
  edited: false,
  days: 90,
  exposures: [],
  fx: 1,
  shield: 0,
  gcsf: { on: false, start: 1, end: 22 },
  tpo: { on: false, start: 1, end: 8 },
  hsct: { on: false, day: 5, dose: 2 },
  profile: structuredClone(DEFAULT_PROFILE),
  params: structuredClone(DEFAULT_PARAMS),
  observations: [],
  obsSource: '',
  compare: null,
  showTable: false,
  last: null,
};

const hub = createHub($('tooltip'));

function loadScenario(id) {
  const c = scenarioConfig(id);
  state.scenarioId = id;
  state.edited = false;
  state.days = c.days;
  state.exposures = c.exposures;
  state.fx = c.exposedFraction;
  state.shield = c.shieldedDoseFactor;
  const find = (k) => c.interventions.find((i) => i.kind === k);
  const g = find('gcsf');
  const t = find('tpo');
  const h = find('hsct');
  state.gcsf = g ? { on: true, start: g.startDay, end: g.endDay } : { on: false, start: 1, end: 22 };
  state.tpo = t ? { on: true, start: t.startDay, end: t.endDay } : { on: false, start: 1, end: 8 };
  state.hsct = h ? { on: true, day: h.day, dose: (h.cellDose ?? 0.02) * 100 } : { on: false, day: 5, dose: 2 };
}

function buildConfig(overrides = {}) {
  const interventions = [];
  if (state.gcsf.on) interventions.push({ kind: 'gcsf', startDay: +state.gcsf.start, endDay: +state.gcsf.end });
  if (state.tpo.on) interventions.push({ kind: 'tpo', startDay: +state.tpo.start, endDay: +state.tpo.end });
  if (state.hsct.on) interventions.push({ kind: 'hsct', day: +state.hsct.day, cellDose: +state.hsct.dose / 100 });
  return {
    exposures: state.exposures,
    exposedFraction: state.fx,
    shieldedDoseFactor: state.shield,
    interventions,
    days: state.days,
    outputStep: state.days > 200 ? 1 : 0.25,
    profile: state.profile,
    params: state.params,
    ...overrides,
  };
}

// ---------- Controls ----------
function populateScenarioSelect() {
  const sel = $('scenario');
  sel.replaceChildren();
  const groups = {};
  for (const s of SCENARIOS) (groups[s.group] ||= []).push(s);
  for (const [name, list] of Object.entries(groups)) {
    const og = document.createElement('optgroup');
    og.label = name;
    for (const s of list) {
      const o = document.createElement('option');
      o.value = s.id;
      o.textContent = s.name;
      og.appendChild(o);
    }
    sel.appendChild(og);
  }
  const custom = document.createElement('option');
  custom.value = 'custom';
  custom.textContent = 'Custom (edited)';
  sel.appendChild(custom);
}

function syncControls() {
  $('scenario').value = state.edited ? 'custom' : state.scenarioId;
  const sc = SCENARIOS.find((s) => s.id === state.scenarioId);
  $('scenario-note').textContent = state.edited ? `Edited from “${sc?.name}”.` : sc?.note || '';
  const daysSel = $('days');
  if (![...daysSel.options].some((o) => +o.value === state.days)) {
    const o = document.createElement('option');
    o.value = state.days;
    o.textContent = `${state.days} days`;
    daysSel.appendChild(o);
  }
  daysSel.value = String(state.days);
  $('fx').value = state.fx;
  $('shield').value = state.shield;
  for (const k of ['gcsf', 'tpo']) {
    $(`${k}-on`).checked = state[k].on;
    $(`${k}-start`).value = state[k].start;
    $(`${k}-end`).value = state[k].end;
  }
  $('hsct-on').checked = state.hsct.on;
  $('hsct-day').value = state.hsct.day;
  $('hsct-dose').value = state.hsct.dose;
  for (const l of LINEAGES) $(`b-${l}`).value = state.profile.baseline[l];
  $('sens').value = state.profile.radiosensitivity;
  $('reserve').value = state.profile.marrowReserve;
  syncParamInputs();
  renderExposureList();
  syncOutputs();
  syncSimple();
}

function syncOutputs() {
  $('fx-out').textContent = Math.round(state.fx * 100) + '%';
  $('shield-out').textContent = Math.round(state.shield * 100) + '% of field dose';
  $('sens-out').textContent = '×' + (+state.profile.radiosensitivity).toFixed(2);
  $('reserve-out').textContent = '×' + (+state.profile.marrowReserve).toFixed(2);
  for (const k of ['gcsf', 'tpo', 'hsct']) {
    $(`${k}-on`).closest('.iv').querySelector('.iv-fields').classList.toggle('off', !state[k].on);
  }
}

function syncParamInputs() {
  const p = state.params;
  $('p-hsc-alpha').value = p.hsc.alpha;
  $('p-hsc-beta').value = p.hsc.beta;
  $('p-hsc-regen').value = p.hsc.regen;
  $('p-repair').value = p.repairHalfTimeHours;
  $('p-doomed').value = p.doomedHalfLife;
  $('p-mtt-n').value = p.lineages.neutrophil.mtt;
}

const EXPOSURE_FIELDS = {
  acute: [
    { key: 'day', label: 'Day', step: 0.5, min: 0 },
    { key: 'dose', label: 'Dose (Gy)', step: 0.1, min: 0 },
    { key: 'durationHours', label: 'Duration (h)', step: 0.5, min: 0 },
    { key: 'fractions', label: 'Fractions', step: 1, min: 1 },
    { key: 'intervalHours', label: 'Interval (h)', step: 1, min: 1 },
  ],
  chronic: [
    { key: 'startDay', label: 'Start day', step: 1, min: 0 },
    { key: 'endDay', label: 'End day', step: 1, min: 0 },
    { key: 'ratemGyPerDay', label: 'mGy/day', step: 0.1, min: 0 },
  ],
};

function renderExposureList() {
  const list = $('exposure-list');
  list.replaceChildren();
  if (!state.exposures.length) {
    const p = document.createElement('p');
    p.className = 'exposure-empty';
    p.textContent = 'No exposures. Add an acute or chronic exposure to see a response.';
    list.appendChild(p);
    return;
  }
  state.exposures.forEach((e, idx) => {
    const box = document.createElement('div');
    box.className = 'exposure';
    const top = document.createElement('div');
    top.className = 'exposure-top';
    const kind = document.createElement('span');
    kind.className = 'exposure-kind';
    kind.textContent = e.kind === 'chronic' ? 'Chronic' : 'Acute';
    const rm = document.createElement('button');
    rm.type = 'button';
    rm.className = 'btn btn-icon';
    rm.textContent = '×';
    rm.setAttribute('aria-label', `Remove exposure ${idx + 1}`);
    rm.addEventListener('click', () => {
      state.exposures.splice(idx, 1);
      markEdited();
      renderExposureList();
      schedule();
    });
    top.append(kind, rm);
    const fields = document.createElement('div');
    fields.className = 'exposure-fields';
    for (const f of EXPOSURE_FIELDS[e.kind === 'chronic' ? 'chronic' : 'acute']) {
      const lab = document.createElement('label');
      lab.className = 'field mini';
      const span = document.createElement('span');
      span.textContent = f.label;
      const inp = document.createElement('input');
      inp.type = 'number';
      inp.id = `exp-${idx}-${f.key}`;
      inp.step = f.step;
      inp.min = f.min;
      const def = f.key === 'fractions' ? 1 : f.key === 'intervalHours' ? 24 : 0;
      inp.value = e[f.key] ?? def;
      inp.addEventListener('input', () => {
        const v = parseFloat(inp.value);
        if (Number.isFinite(v)) {
          e[f.key] = v;
          markEdited();
          schedule();
        }
      });
      lab.append(span, inp);
      fields.appendChild(lab);
    }
    box.append(top, fields);
    list.appendChild(box);
  });
}

function markEdited() {
  if (!state.edited) {
    state.edited = true;
    $('scenario').value = 'custom';
    const sc = SCENARIOS.find((s) => s.id === state.scenarioId);
    $('scenario-note').textContent = `Edited from “${sc?.name}”.`;
  }
}

function bindControls() {
  $('scenario').addEventListener('change', (ev) => {
    if (ev.target.value === 'custom') return;
    loadScenario(ev.target.value);
    syncControls();
    schedule(0);
  });
  $('days').addEventListener('change', (ev) => {
    state.days = +ev.target.value;
    schedule(0);
  });
  $('add-acute').addEventListener('click', () => {
    state.exposures.push({ kind: 'acute', day: 0, dose: 1, durationHours: 0, fractions: 1, intervalHours: 24 });
    markEdited();
    renderExposureList();
    schedule();
  });
  $('add-chronic').addEventListener('click', () => {
    state.exposures.push({ kind: 'chronic', startDay: 0, endDay: state.days, ratemGyPerDay: 1 });
    markEdited();
    renderExposureList();
    schedule();
  });
  $('fx').addEventListener('input', (ev) => { state.fx = +ev.target.value; markEdited(); syncOutputs(); schedule(); });
  $('shield').addEventListener('input', (ev) => { state.shield = +ev.target.value; markEdited(); syncOutputs(); schedule(); });
  for (const k of ['gcsf', 'tpo']) {
    $(`${k}-on`).addEventListener('change', (ev) => { state[k].on = ev.target.checked; markEdited(); syncOutputs(); schedule(); });
    $(`${k}-start`).addEventListener('input', (ev) => { state[k].start = +ev.target.value; markEdited(); schedule(); });
    $(`${k}-end`).addEventListener('input', (ev) => { state[k].end = +ev.target.value; markEdited(); schedule(); });
  }
  $('hsct-on').addEventListener('change', (ev) => { state.hsct.on = ev.target.checked; markEdited(); syncOutputs(); schedule(); });
  $('hsct-day').addEventListener('input', (ev) => { state.hsct.day = +ev.target.value; markEdited(); schedule(); });
  $('hsct-dose').addEventListener('input', (ev) => { state.hsct.dose = +ev.target.value; markEdited(); schedule(); });
  for (const l of LINEAGES) {
    $(`b-${l}`).addEventListener('input', (ev) => {
      const v = parseFloat(ev.target.value);
      if (v > 0) { state.profile.baseline[l] = v; schedule(); }
    });
  }
  $('sens').addEventListener('input', (ev) => { state.profile.radiosensitivity = +ev.target.value; syncOutputs(); schedule(); });
  $('reserve').addEventListener('input', (ev) => { state.profile.marrowReserve = +ev.target.value; syncOutputs(); schedule(); });

  const paramMap = [
    ['p-hsc-alpha', (p, v) => { p.hsc.alpha = v; }],
    ['p-hsc-beta', (p, v) => { p.hsc.beta = v; }],
    ['p-hsc-regen', (p, v) => { p.hsc.regen = v; }],
    ['p-repair', (p, v) => { p.repairHalfTimeHours = v; }],
    ['p-doomed', (p, v) => { p.doomedHalfLife = v; }],
    ['p-mtt-n', (p, v) => { p.lineages.neutrophil.mtt = v; }],
  ];
  for (const [id, set] of paramMap) {
    $(id).addEventListener('input', (ev) => {
      const v = parseFloat(ev.target.value);
      if (Number.isFinite(v) && v >= 0) { set(state.params, v); schedule(); }
    });
  }
  $('reset-params').addEventListener('click', () => {
    state.params = structuredClone(DEFAULT_PARAMS);
    syncParamInputs();
    schedule(0);
  });

  $('pin-btn').addEventListener('click', () => {
    if (!state.last) return;
    const sc = SCENARIOS.find((s) => s.id === state.scenarioId);
    state.compare = { res: state.last.res, label: state.edited ? 'Pinned (custom)' : `Pinned: ${sc.name}` };
    $('unpin-btn').hidden = false;
    $('compare-key').hidden = false;
    renderAll();
  });
  $('unpin-btn').addEventListener('click', () => {
    state.compare = null;
    $('unpin-btn').hidden = true;
    $('compare-key').hidden = true;
    renderAll();
  });

  $('csv-file').addEventListener('change', async (ev) => {
    const f = ev.target.files?.[0];
    if (!f) return;
    try {
      loadObservations(await f.text(), f.name);
    } catch (err) {
      setObsStatus(err.message, true);
    }
    ev.target.value = '';
  });
  $('load-example').addEventListener('click', () => loadObservations(SYNTHETIC_CSV, 'synthetic example (2 Gy acute, generated by the model)', true));
  $('clear-obs').addEventListener('click', () => {
    state.observations = [];
    $('fit-result').hidden = true;
    $('clear-obs').hidden = true;
    $('fit-btn').disabled = true;
    setObsStatus('');
    renderAll();
  });
  $('fit-btn').addEventListener('click', runFit);

  $('toggle-table').addEventListener('click', () => {
    state.showTable = !state.showTable;
    $('toggle-table').textContent = state.showTable ? 'Hide table' : 'Show table';
    $('toggle-table').setAttribute('aria-expanded', String(state.showTable));
    $('table-wrap').hidden = !state.showTable;
    if (state.showTable) renderTable();
  });
  $('copy-csv').addEventListener('click', async () => {
    const csv = resultsCSV();
    try {
      await navigator.clipboard.writeText(csv);
      $('copy-status').textContent = `Copied ${csv.split('\n').length - 1} rows to the clipboard.`;
    } catch {
      if (!state.showTable) $('toggle-table').click();
      $('copy-status').textContent = 'Clipboard access was blocked. The table below holds the same values.';
    }
  });

  let resizeTimer;
  new ResizeObserver(() => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(renderCharts, 80);
  }).observe(document.querySelector('.results'));
}

function setObsStatus(msg, error = false) {
  const el = $('obs-status');
  el.textContent = msg;
  el.classList.toggle('error', error);
}

function loadObservations(text, source, isExample = false) {
  const rows = parseObservationsCSV(text);
  if (!rows.length) throw new Error('No rows with a recognised target were found in that file.');
  state.observations = rows;
  state.obsSource = source;
  if (isExample) {
    // The example was generated with a 2 Gy acute exposure. Match it so the fit is meaningful.
    state.exposures = [{ kind: 'acute', day: 0, dose: 2, durationHours: 0, fractions: 1, intervalHours: 24 }];
    state.fx = 1;
    state.shield = 0;
    state.gcsf.on = state.tpo.on = state.hsct.on = false;
    if (state.days < 30) state.days = 30;
    markEdited();
    syncControls();
  }
  const targets = new Set(rows.map((r) => r.target)).size;
  setObsStatus(`${rows.length} observations across ${targets} targets from ${source}.${isExample ? ' Exposure set to 2 Gy acute to match.' : ''}`);
  $('fit-btn').disabled = false;
  $('clear-obs').hidden = false;
  $('fit-result').hidden = true;
  schedule(0);
}

function runFit() {
  const btn = $('fit-btn');
  btn.disabled = true;
  btn.textContent = 'Fitting…';
  setTimeout(() => {
    try {
      const fitReserve = $('fit-reserve').checked;
      const cfg = buildConfig({ outputStep: 0.25 });
      const best = fitProfile(cfg, state.observations, fitReserve
        ? { fitReserve: true, sensGrid: grid(0.4, 2, 0.1), reserveGrid: grid(0.5, 2, 0.25) }
        : {});
      showFit(best, fitReserve);
    } catch (err) {
      setObsStatus(err.message, true);
    } finally {
      btn.disabled = false;
      btn.textContent = 'Fit profile to data';
    }
  }, 30);
}

function grid(a, b, s) {
  const out = [];
  for (let v = a; v <= b + 1e-9; v += s) out.push(Math.round(v * 100) / 100);
  return out;
}

function showFit(best, fitReserve) {
  const box = $('fit-result');
  box.replaceChildren();
  const dl = document.createElement('dl');
  const add = (k, v) => {
    const dt = document.createElement('dt');
    dt.textContent = k;
    const dd = document.createElement('dd');
    dd.textContent = v;
    dl.append(dt, dd);
  };
  add('Radiosensitivity', '×' + best.radiosensitivity.toFixed(2));
  if (fitReserve) add('Regenerative reserve', '×' + best.marrowReserve.toFixed(2));
  add('Fit error (RMS log ratio)', best.rmseLog.toFixed(3));
  add('Observations', String(best.n));
  const note = document.createElement('p');
  note.className = 'hint';
  note.textContent = 'Grid search over the multiplier(s), minimising squared log error between model and observations under the exposures currently set.';
  const apply = document.createElement('button');
  apply.type = 'button';
  apply.className = 'btn btn-small btn-primary';
  apply.textContent = 'Apply to profile';
  apply.addEventListener('click', () => {
    state.profile.radiosensitivity = best.radiosensitivity;
    if (fitReserve) state.profile.marrowReserve = best.marrowReserve;
    state.profile.name = 'Calibrated profile';
    syncControls();
    schedule(0);
  });
  box.append(dl, note, apply);
  box.hidden = false;
}

// ---------- Rendering ----------
let timer;
function schedule(delay = 60) {
  clearTimeout(timer);
  timer = setTimeout(renderAll, delay);
}

function renderAll() {
  const cfg = buildConfig();
  const res = simulate(cfg);
  const sum = summarize(res);
  state.last = { cfg, res, sum };
  renderSummary();
  if ($('expert').open) renderCharts();
  if (state.showTable) renderTable();
  onModelUpdated();
}

function renderSummary() {
  const { sum, res } = state.last;
  const cmp = state.compare ? summarize(state.compare.res) : null;
  const root = $('summary');
  root.replaceChildren();

  const verdict = document.createElement('div');
  verdict.className = 'verdict';
  const main = document.createElement('div');
  main.className = 'verdict-main';
  main.append(pill(sum.worstGrade, `Grade ${sum.worstGrade}`));
  const vt = document.createElement('span');
  vt.textContent = GRADE_TEXT[sum.worstGrade];
  main.append(vt);
  const facts = document.createElement('div');
  facts.className = 'verdict-facts';
  const anc = sum.neutrophil;
  const fact = (label, value) => {
    const s = document.createElement('span');
    s.append(label + ' ');
    const b = document.createElement('b');
    b.textContent = value;
    s.append(b);
    facts.append(s);
  };
  fact('Marrow dose', `${fmtNum(sum.totalDose, sum.totalDose < 1 ? 3 : 2)} Gy`);
  fact('Marrow in field', `${Math.round(res.exposedFraction * 100)}%`);
  fact('Lowest stem-cell pool', fmtPct(sum.hscNadir));
  fact('Stem cells at end', fmtPct(sum.hscFinal));
  fact('ANC < 0.5 for', `${fmtNum(anc.daysGrade4, 1)} days`);
  verdict.append(main, facts);
  root.append(verdict);

  const tiles = document.createElement('div');
  tiles.className = 'tiles';
  for (const l of LINEAGES) {
    const s = sum[l];
    const info = LINEAGE_INFO[l];
    const tile = document.createElement('div');
    tile.className = 'tile';
    const lab = document.createElement('div');
    lab.className = 'tile-label';
    const name = document.createElement('span');
    name.textContent = `${info.label} nadir`;
    lab.append(name, pill(s.worstGrade, `G${s.worstGrade}`));
    const val = document.createElement('div');
    val.className = 'tile-value';
    val.textContent = fmtNum(s.nadir);
    const unit = document.createElement('small');
    unit.textContent = info.unit;
    val.append(unit);
    const meta = document.createElement('div');
    meta.className = 'tile-meta';
    const line = (parts) => {
      const d = document.createElement('span');
      for (const p of parts) {
        if (typeof p === 'string') d.append(p);
        else {
          const b = document.createElement('b');
          b.textContent = p.b;
          d.append(b);
        }
      }
      meta.append(d);
    };
    const changed = s.nadirRel < 0.98;
    line(changed ? ['on day ', { b: fmtNum(s.nadirDay, 0) }, ` · ${fmtPct(s.nadirRel)} of baseline`] : ['No meaningful drop']);
    if (s.daysGrade3 > 0) line(['Grade ≥3 for ', { b: fmtNum(s.daysGrade3, 1) }, ' days']);
    if (s.nadirRel < 0.8) {
      line(s.recoveryDay != null ? ['Back to 80% by day ', { b: fmtNum(s.recoveryDay, 0) }] : ['Below 80% at end of horizon']);
    }
    tile.append(lab, val, meta);
    if (cmp) {
      const d = document.createElement('div');
      d.className = 'tile-delta';
      d.textContent = `Pinned run: ${fmtNum(cmp[l].nadir)} on day ${fmtNum(cmp[l].nadirDay, 0)}`;
      tile.append(d);
    }
    tiles.append(tile);
  }
  root.append(tiles);
}

function pill(grade, text) {
  const s = document.createElement('span');
  s.className = `pill g${grade}`;
  s.textContent = text;
  return s;
}

function renderCharts() {
  if (!state.last) return;
  const { res, cfg } = state.last;
  hub.reset();
  const days = cfg.days;
  const pulses = expandExposures(cfg.exposures.filter((e) => e.kind !== 'chronic'));
  const chronic = cfg.exposures.filter((e) => e.kind === 'chronic');
  timelineChart($('timeline'), { days, pulses, chronic, interventions: cfg.interventions, hub });
  const total = res.cumDose[res.cumDose.length - 1];
  $('timeline-sub').textContent = pulses.length || chronic.length
    ? `Total marrow dose ${fmtNum(total, total < 1 ? 3 : 2)} Gy. Bar height is proportional to dose.`
    : 'No exposures set.';

  const cmp = state.compare?.res;
  for (const l of LINEAGES) {
    const info = LINEAGE_INFO[l];
    const bounds = CTCAE[l];
    const thresholds = [];
    if (l === 'rbc') {
      thresholds.push({ value: bounds[1], label: 'G2', band: 'g3' }, { value: bounds[2], label: 'G3', band: 'g4' });
    } else {
      thresholds.push({ value: bounds[2], label: 'G3', band: 'g3' }, { value: bounds[3], label: 'G4', band: 'g4' });
    }
    const series = [{ label: 'Model', color: 'var(--series-1)', values: res.blood[l] }];
    if (cmp) series.push({ label: state.compare.label, color: 'var(--compare)', values: cmp.blood[l], t: cmp.t, dash: true });
    const base = state.profile.baseline[l];
    const points = state.observations
      .filter((o) => o.target === l)
      .map((o) => ({ x: o.day, y: o.value * base, color: 'var(--ink-2)' }));
    const s = state.last.sum[l];
    lineChart($(`chart-${l}`), {
      t: res.t, days, series, title: info.label, unit: info.unit, thresholds, points, hub,
      yMaxMin: base * 1.1,
      nadir: s.nadirRel < 0.95 ? { day: s.nadirDay, value: s.nadir } : null,
      format: (v) => `${fmtNum(v)} ${info.unit}`,
      ariaLabel: `${info.label} over ${days} days. Nadir ${fmtNum(s.nadir)} ${info.unit} on day ${fmtNum(s.nadirDay, 0)}.`,
    });
  }

  const mseries = MARROW_SERIES.map((m) => ({ label: m.label, color: m.color, values: res.marrow[m.key] }));
  if (cmp) mseries.push({ label: `${state.compare.label} · HSC`, color: 'var(--compare)', values: cmp.marrow.hsc, t: cmp.t, dash: true });
  const colorFor = Object.fromEntries(MARROW_SERIES.map((m) => [m.key, m.color]));
  const mpoints = state.observations
    .filter((o) => o.target === 'hsc' || o.target.startsWith('progenitor:'))
    .map((o) => ({ x: o.day, y: o.value, color: colorFor[o.target === 'hsc' ? 'hsc' : o.target.split(':')[1]] }));
  lineChart($('chart-marrow'), {
    t: res.t, days, series: mseries, title: 'Marrow pools', unit: '% of pre-exposure', log: true, logFloor: 1e-4,
    points: mpoints, hub, height: 300, endLabels: false, format: fmtPct,
    ariaLabel: `Marrow stem cell and progenitor pools over ${days} days, log scale.`,
  });
  renderMarrowLegend(Boolean(cmp));
  hub.setToday(play.day);
}

function renderMarrowLegend(withCompare) {
  const el = $('marrow-legend');
  el.replaceChildren();
  const item = (label, color, dash) => {
    const s = document.createElement('span');
    s.className = 'legend-item';
    const sw = document.createElement('span');
    sw.className = 'legend-swatch';
    sw.style.borderTopColor = color;
    if (dash) sw.style.borderTopStyle = 'dashed';
    const t = document.createElement('span');
    t.textContent = label;
    s.append(sw, t);
    el.append(s);
  };
  for (const m of MARROW_SERIES) item(m.label, m.color);
  if (withCompare) item('Pinned run · HSC', 'var(--compare)', true);
  if (state.observations.some((o) => o.target === 'hsc' || o.target.startsWith('progenitor:'))) {
    const s = document.createElement('span');
    s.className = 'legend-item';
    const d = document.createElement('span');
    d.className = 'legend-dot';
    const t = document.createElement('span');
    t.textContent = 'Observed (loaded data)';
    s.append(d, t);
    el.append(s);
  }
}

function tableRows() {
  const { res, cfg } = state.last;
  const every = Math.max(1, Math.round(cfg.days / 90));
  const rows = [];
  for (let i = 0; i < res.t.length; i++) {
    const d = res.t[i];
    if (Math.abs(d - Math.round(d)) > 1e-6 || Math.round(d) % every !== 0) continue;
    rows.push([
      d,
      res.blood.neutrophil[i], res.blood.platelet[i], res.blood.rbc[i], res.blood.lymphocyte[i],
      res.marrow.hsc[i], res.marrow.neutrophil[i], res.marrow.platelet[i], res.marrow.rbc[i], res.marrow.lymphocyte[i],
      res.cumDose[i],
    ]);
  }
  return rows;
}
const TABLE_HEAD = ['Day', 'ANC', 'PLT', 'Hgb', 'ALC', 'HSC %', 'Myeloid %', 'Mega %', 'Erythroid %', 'Lymphoid %', 'Cum. dose Gy'];

function renderTable() {
  const wrap = $('table-wrap');
  const table = document.createElement('table');
  const thead = document.createElement('thead');
  const hr = document.createElement('tr');
  for (const h of TABLE_HEAD) {
    const th = document.createElement('th');
    th.textContent = h;
    hr.append(th);
  }
  thead.append(hr);
  const tbody = document.createElement('tbody');
  for (const r of tableRows()) {
    const tr = document.createElement('tr');
    r.forEach((v, k) => {
      const td = document.createElement('td');
      td.textContent = k === 0 ? String(v) : k >= 5 && k <= 9 ? (v * 100).toFixed(2) : fmtNum(v, k === 2 ? 0 : 2);
      tr.append(td);
    });
    tbody.append(tr);
  }
  table.append(thead, tbody);
  wrap.replaceChildren(table);
}

function resultsCSV() {
  const head = ['day', 'anc_1e9_per_L', 'platelets_1e9_per_L', 'hgb_g_per_dL', 'alc_1e9_per_L', 'hsc_rel', 'myeloid_prog_rel', 'mega_prog_rel', 'erythroid_prog_rel', 'lymphoid_prog_rel', 'cumulative_dose_Gy'];
  const lines = [head.join(',')];
  for (const r of tableRows()) lines.push(r.map((v, k) => (k === 0 ? v : +v.toPrecision(5))).join(','));
  return lines.join('\n');
}

// =====================================================================
